      "citations": []
    },
    {
      "kind": "qualitative",
      "text": "Oracle operates three businesses—cloud and software, hardware, and services—with each business comprised of a single operating segment.",
      "citations": [
        {
          "chunk_id": "ORCL-000119312526277521-0010",
          "quote": "We have three businesses: cloud and software (formerly referred to as cloud and license); hardware; and services. Each business is comprised of a single operating segment."
        }
      ]
    },
    {
      "kind": "qualitative",
      "text": "Oracle delivers its cloud offerings through a secure, reliable, scalable, enterprise grade cloud infrastructure platform managed by Oracle employees within a global network of data centers, and it has invested in rapid expansion by adding data centers in new geographic locations to meet expected customer demand.",
      "citations": [
        {
          "chunk_id": "ORCL-000119312526277521-0035",
          "quote": "through a secure, reliable, scalable, enterprise grade cloud infrastructure platform managed by Oracle employees within a global network of data centers"
        },
        {
          "chunk_id": "ORCL-000119312526277521-0035",
          "quote": "We have invested in the rapid expansion of the Oracle Cloud by increasing existing data center capacity and adding data centers in new geographic locations"
        }
      ]
    },
    {
      "kind": "qualitative",
      "text": "After an initial purchase of Oracle products and services, customers can continue to purchase and renew Oracle support offerings and renew their Oracle Cloud contracts.",
      "citations": [
        {
          "chunk_id": "ORCL-000119312526277521-0010",
          "quote": "After an initial purchase of Oracle products and services, our customers can continue to benefit"
        },
        {
          "chunk_id": "ORCL-000119312526277521-0010",
          "quote": "by electing to purchase and renew Oracle support offerings for their software and hardware deployments"
        },
        {
          "chunk_id": "ORCL-000119312526277521-0010",
          "quote": "and by renewing their Oracle Cloud contracts with us"
        }
      ]
    },
    {
      "kind": "qualitative",
      "text": "Oracle's services business, which represented 8% and 9% of our total revenues in fiscal 2026 and 2025, respectively, has lower margins than its cloud and software and hardware businesses, and its revenues are affected by general economic conditions and tighter controls over customer discretionary spending.",
      "citations": [
        {
          "chunk_id": "ORCL-000119312526277521-0166",
          "quote": "which represented 8% and 9% of our total revenues in fiscal 2026 and 2025, respectively"
        },
        {
          "chunk_id": "ORCL-000119312526277521-0166",
          "quote": "Our services business has lower margins than our cloud and software and hardware businesses."
        },
        {
          "chunk_id": "ORCL-000119312526277521-0166",
          "quote": "general economic conditions; governmental budgetary constraints; personnel reductions in our customers’ IT departments; tighter controls over customer discretionary spending; and foreign currency rate fluctuations."
        }
      ]
    }
  ]
}

{
